import java.io.*;
import javax.servlet.http.*;

public class UserServlet extends HttpServlet {
    // Vulnerable: Deserializing untrusted data from an HTTP request
    protected void doPost(HttpServletRequest request, HttpServletResponse response) {
        try {
            // Read serialized object from request input stream
            ObjectInputStream ois = new ObjectInputStream(request.getInputStream());
            Object obj = ois.readObject(); // vulnerable line

            // Do something with the object
            response.getWriter().println("Received object: " + obj.toString());
